'use strict';

// MAIN //

/**
* Evaluates the identity function for a 64-bit signed integer `x`.
*
* @param {Int64} x - input value
* @returns {Int64} input value
*
* @example
* import Int64 from '@stdlib/number-int64-ctor';
*
* var x = new Int64( 1 );
* var v = identity( x );
* // returns <Int64>[ 1n ]
*
* @example
* import Int64 from '@stdlib/number-int64-ctor';
*
* var x = new Int64( 0 );
* var v = identity( x );
* // returns <Int64>[ 0n ]
*
* @example
* import Int64 from '@stdlib/number-int64-ctor';
*
* var x = new Int64( 4294967296 );
* var v = identity( x );
* // returns <Int64>[ 4294967296n ]
*
* @example
* import Int64 from '@stdlib/number-int64-ctor';
*
* var x = new Int64( -1000000000000 );
* var v = identity( x );
* // returns <Int64>[ -1000000000000n ]
*/
function identity( x ) {
	return x;
}


// EXPORTS //

export default identity;
